skills.coin_approach:
def coin_approach(evidence):
    state = tool('coin_status', {})['result']
    if state['next_stage'] != 'approach' or state['pending_stage'] is not None:
        raise RuntimeError('Expected a fresh prepared open-hand approach')
    obs = get_observation()
    tool('coin_step', {'step': obs['step']})
    obs = get_observation()
    return tool('coin_servo', {'step': obs['step'], 'evidence': evidence})

skills.coin_acquire:
def coin_acquire(evidence):
    obs = get_observation()
    tool('coin_servo_accept', {'step': obs['step'], 'evidence': evidence})
    for phase in range(2):
        obs = get_observation()
        tool('coin_step', {'step': obs['step']})
    return get_observation()

skills.coin_confirm_and_lift:
def coin_confirm_and_lift(evidence):
    obs = get_observation()
    tool('coin_review_probe', {'step': obs['step'], 'assessment': 'held', 'evidence': evidence})
    tool('coin_step', {'step': obs['step']})
    return get_observation()

skills.coin_finish_pickup:
def coin_finish_pickup(assessment, evidence):
    obs = get_observation()
    tool('coin_review_pickup', {'step': obs['step'], 'assessment': assessment, 'evidence': evidence})
    return tool('finish', {})

skills.coin_finish_empty:
def coin_finish_empty():
    state = tool('coin_status', {})['result']
    if state['next_stage'] != 'withdraw' or state['pending_stage'] is not None:
        raise RuntimeError('Release must have completed before withdrawal/home')
    for phase in range(2):
        obs = get_observation()
        tool('coin_step', {'step': obs['step']})
    return get_observation()
